// K-way merge over heterogeneous timeline sources (the local Warpnet
// timeline plus one source per followed fediverse handle). Each source keeps
// its own opaque cursor — a Badger key on the Warpnet side, a gateway URL on
// the fediverse side — so cursors are never combined into one token.
//
// Ordering contract: emission pops the newest `created_at` among the heads
// of the sources' buffers, and the fetch order inside a source is never
// re-sorted. Sources that don't answer within the per-page prime budget are
// excluded from that page only — their in-flight fetch keeps running and
// fills the buffer for the next page (append-only; rendered rows are never
// re-ordered).

const END_CURSOR = 'end';
// A source returning empty-but-not-exhausted pages (e.g. every item
// filtered out) is refetched at most this many times per page cycle.
const MAX_FETCHES_PER_CYCLE = 3;
// One failure is retried on the next page; this many consecutive failing
// cycles write the source off as terminal, so a dead gateway can't keep
// endOfFeed false (and the scroll spinner alive) forever.
const MAX_CONSECUTIVE_FAILURES = 2;

function itemTs(item) {
    const ts = new Date(item && item.created_at).getTime();
    return Number.isNaN(ts) ? 0 : ts;
}

// Resolves true when `ms` elapses before `promise` settles.
function timedOut(promise, ms) {
    if (ms <= 0) {
        return Promise.resolve(true);
    }
    return new Promise((resolve) => {
        const timer = setTimeout(() => resolve(true), ms);
        promise.then(() => {
            clearTimeout(timer);
            resolve(false);
        });
    });
}

export function createTimelineMerger({
    sources,
    pageSize = 20,
    primeTimeoutMs = 3500,
    concurrency = 4,
    applyFilters = async (tweets) => tweets,
}) {
    const state = (sources || []).map((src) => ({
        id: src.id,
        fetchPage: src.fetchPage,
        prefiltered: !!src.prefiltered,
        skipRefresh: !!src.skipRefresh,
        buffer: [],
        pendingFilter: [],
        cursor: '',
        exhausted: false,
        failed: false,
        inFlight: null,
        newestTs: 0,
        cycleFetches: 0,
        consecutiveFailures: 0,
    }));
    const seenIds = new Set();
    let generation = 0;

    const isLive = (s) => !s.exhausted && !s.failed
        && s.consecutiveFailures < MAX_CONSECUTIVE_FAILURES;

    function fetchOnce(s) {
        if (s.inFlight) {
            return s.inFlight;
        }
        const gen = generation;
        s.cycleFetches++;
        s.inFlight = (async () => {
            try {
                const page = await s.fetchPage(s.cursor);
                if (gen !== generation) {
                    return;
                }
                const items = ((page && page.tweets) || []).filter((t) => t && t.id);
                for (const t of items) {
                    s.newestTs = Math.max(s.newestTs, itemTs(t));
                }
                if (s.prefiltered) {
                    s.buffer.push(...items);
                } else {
                    s.pendingFilter.push(...items);
                }
                s.cursor = (page && page.cursor) || END_CURSOR;
                if (s.cursor === END_CURSOR) {
                    s.exhausted = true;
                }
                s.consecutiveFailures = 0;
            } catch (err) {
                if (gen === generation) {
                    s.failed = true;
                    s.consecutiveFailures++;
                    console.warn(`timeline source ${s.id} failed:`, err);
                }
            } finally {
                if (gen === generation) {
                    s.inFlight = null;
                }
            }
        })();
        return s.inFlight;
    }

    // One filter pass per call over everything fetched since the last pass —
    // a single keyword-filters roundtrip per page cycle, matching what a
    // plain timeline page costs today. On filter failure items pass through:
    // showing an unfiltered post beats silently dropping the feed.
    async function filterPending() {
        const taken = new Map();
        const batch = [];
        for (const s of state) {
            if (s.pendingFilter.length === 0) {
                continue;
            }
            const items = s.pendingFilter.splice(0);
            taken.set(s, items);
            batch.push(...items);
        }
        if (batch.length === 0) {
            return;
        }
        let survivors;
        try {
            survivors = await applyFilters(batch);
        } catch (err) {
            console.warn('timeline filters unavailable, passing items through:', err);
            survivors = batch;
        }
        const ok = new Set((survivors || []).map((t) => t && t.id));
        for (const [s, items] of taken) {
            s.buffer.push(...items.filter((t) => ok.has(t.id)));
        }
    }

    // Fetch pages for `list` in pool-sized batches until the deadline; a
    // source that misses the deadline goes into `late` (skipped for this
    // page, its in-flight fetch keeps filling the buffer for the next one).
    async function prime(list, deadline, late) {
        for (let i = 0; i < list.length; i += concurrency) {
            const remaining = deadline - Date.now();
            const batch = list.slice(i, i + concurrency);
            if (remaining <= 0) {
                batch.forEach((s) => late.add(s.id));
                list.slice(i + concurrency).forEach((s) => late.add(s.id));
                return;
            }
            const settled = Promise.allSettled(batch.map((s) => fetchOnce(s)));
            if (await timedOut(settled, remaining)) {
                for (const s of list) {
                    if (isLive(s) && s.buffer.length === 0 && s.pendingFilter.length === 0) {
                        late.add(s.id);
                    }
                }
                return;
            }
        }
    }

    async function nextPage() {
        const deadline = Date.now() + primeTimeoutMs;
        const late = new Set();
        for (const s of state) {
            s.failed = false;
            s.cycleFetches = 0;
        }

        const emitted = [];
        while (emitted.length < pageSize) {
            const empties = state.filter(
                (s) => isLive(s) && !late.has(s.id)
                    && s.buffer.length === 0 && s.pendingFilter.length === 0
                    && s.cycleFetches < MAX_FETCHES_PER_CYCLE,
            );
            if (empties.length > 0) {
                await prime(empties, deadline, late);
                await filterPending();
                continue;
            }
            await filterPending();
            const heads = state.filter((s) => s.buffer.length > 0);
            if (heads.length === 0) {
                break;
            }
            let best = heads[0];
            for (const s of heads) {
                if (itemTs(s.buffer[0]) > itemTs(best.buffer[0])) {
                    best = s;
                }
            }
            const item = best.buffer.shift();
            if (!seenIds.has(item.id)) {
                seenIds.add(item.id);
                emitted.push(item);
            }
        }
        return { tweets: emitted, done: isDone() };
    }

    // First-page re-fetch per refreshable source, returning only items newer
    // than anything that source has ever produced. Paging cursors are not
    // moved, so a poll can never skip a page for the scroll path. A source
    // that has never yielded anything (still cold) is left to nextPage —
    // prepending its whole backlog would dump old posts on top of the feed.
    async function refreshNewest() {
        const targets = state.filter(
            (s) => !s.skipRefresh && (s.newestTs > 0 || s.exhausted),
        );
        const collected = [];
        for (let i = 0; i < targets.length; i += concurrency) {
            const batch = targets.slice(i, i + concurrency);
            const pages = await Promise.allSettled(batch.map((s) => s.fetchPage('')));
            pages.forEach((res, n) => {
                if (res.status !== 'fulfilled') {
                    return;
                }
                const s = batch[n];
                const fresh = ((res.value && res.value.tweets) || []).filter(
                    (t) => t && t.id && !seenIds.has(t.id) && itemTs(t) > s.newestTs,
                );
                if (fresh.length > 0) {
                    collected.push({ source: s, items: fresh });
                }
            });
        }
        const all = collected.flatMap((c) => c.items);
        if (all.length === 0) {
            return [];
        }
        let survivors = all;
        try {
            survivors = (await applyFilters(all)) || [];
        } catch (err) {
            console.warn('timeline filters unavailable, passing items through:', err);
        }
        const ok = new Set(survivors.map((t) => t && t.id));
        const result = [];
        for (const { source, items } of collected) {
            for (const t of items) {
                source.newestTs = Math.max(source.newestTs, itemTs(t));
                if (ok.has(t.id) && !seenIds.has(t.id)) {
                    seenIds.add(t.id);
                    result.push(t);
                }
            }
        }
        return result.sort((a, b) => itemTs(b) - itemTs(a));
    }

    function isDone() {
        return state.every(
            (s) => (s.exhausted || s.consecutiveFailures >= MAX_CONSECUTIVE_FAILURES)
                && !s.inFlight
                && s.buffer.length === 0 && s.pendingFilter.length === 0,
        );
    }

    function reset() {
        generation++;
        seenIds.clear();
        for (const s of state) {
            s.buffer = [];
            s.pendingFilter = [];
            s.cursor = '';
            s.exhausted = false;
            s.failed = false;
            s.inFlight = null;
            s.newestTs = 0;
            s.cycleFetches = 0;
            s.consecutiveFailures = 0;
        }
    }

    // The newest created_at this source has ever fetched (0 if none) — the
    // reference point for "is this actually new?" checks outside the merger.
    function sourceNewestTs(id) {
        const s = state.find((x) => x.id === id);
        return s ? s.newestTs : 0;
    }

    return {
        nextPage,
        refreshNewest,
        reset,
        sourceNewestTs,
        get done() {
            return isDone();
        },
    };
}
